    for (std::size_t i = 0; i < static_cast<std::size_t>(InputCount) * HiddenSize; ++i) {
#if FORGE_HAS_NNUE
        const float expected = static_cast<float>(NnueW1[i]) / WeightScale;
#else
        const float expected = 0.0F;
#endif
        values_exact &= std::bit_cast<std::uint32_t>(w.w1[i]) == std::bit_cast<std::uint32_t>(expected);
